#include <iostream>
#include <string>
int main() {
    std::string s = "level";
    bool ok = true;
    for (int i = 0; i < s.size() / 2; i++)
        if (s[i] != s[s.size() - 1 - i]) ok = false;
    std::cout << (ok ? "yes" : "no") << "\n";
    return 0;
}

