#include <iostream>
#include <string>
int main() {
    std::string s = "abababa";
    int count = 0;
    for (int i = 0; i + 2 < s.size(); i++)
        if (s.substr(i, 3) == "aba") count++;
    std::cout << count << "\n";
    return 0;
}

#include <iostream>
#include <string>
int main() {
    std::string s = "aabbcc";
    int freq[26] = {0};
    for (char c : s) freq[c - 'a']++;
    int distinct = 0;
    for (int i = 0; i < 26; i++) if (freq[i] > 0) distinct++;
    std::cout << distinct << "\n";
    return 0;
}
